val films = List(
  ("Inception", List("科幻", "惊悚")),
  ("The Dark Knight", List("动作", "犯罪", "剧情")),
  ("Interstellar", List("冒险", "剧情", "科幻")),
  ("Pulp Fiction", List("犯罪", "剧情"))
)
val directors = Map(
  "Christopher Nolan" -> List("Inception", "The Dark Knight", "Interstellar"),
  "Quentin Tarantino" -> List("Pulp Fiction", "Kill Bill", "Django Unchained"),
  "Spike Lee" -> List("Do the Right Thing", "Malcolm X", "BlacKkKlansman")
)
val palmeDOr = Map(
  "Apocalypse Now" -> 1979,
  "The Tree of Life" -> 2011,
  "Pulp Fiction" -> 1994,
  "The Piano" -> 1993,
  "Taxi Driver" -> 1976,
  "MASH" -> 1970,
  "La Dolce Vita" -> 1960,
  "The Cranes Are Flying" -> 1957
)
