以下是一个Java代码实现程序，用于检查句子是否遵循SVO结构：

```java
import java.util.Scanner;

public class SVOChecker {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("请输入一个句子：");
        String sentence = scanner.nextLine();
        boolean isSVO = checkSVO(sentence);
        if (isSVO) {
            System.out.println("该句子遵循SVO结构。");
        } else {
            System.out.println("该句子不遵循SVO结构。");
        }
    }

    public static boolean checkSVO(String sentence) {
        String[] words = sentence.split(" ");
        if (words.length != 3) {
            return false;
        }
        String subject = words[0];
        String verb = words[1];
        String object = words[2];
        if (verb.endsWith("s")) {
            // 第三人称单数形式的动词需要特殊处理
            if (subject.endsWith("s") || subject.endsWith("sh") || subject.endsWith("ch") || subject.endsWith("x") || subject.endsWith("o")) {
                subject += "es";
            } else {
                subject += "s";
            }
        }
        String expectedSentence = subject + " " + verb + " " + object;
        return sentence.equalsIgnoreCase(expectedSentence);
    }
}
```

