```
// 获取输入框和结果显示框对象
var inputBox = document.getElementById('inputBox');
var result = document.getElementById('result');
// 输入函数，将数字或者小数点添加到输入框中
function input(value) {
  inputBox.value += value;
}
// 清空输入框
function clearInput() {
  inputBox.value = '';
  result.innerHTML = '0';
}
// 计算函数
function calculate(operator) {
  var expression = inputBox.value;   // 获取输入表达式
  var operands = expression.split(operator);      // 将表达式按照运算符拆分为两个操作数
  var op1 = parseFloat(operands[0]);      // 将第一个操作数转换为浮点数
  var op2 = parseFloat(operands[1]);      // 将第二个操作数转换为浮点数
  var res = '';     // 计算结果
  // 根据运算符进行相应的计算
  switch (operator) {
    case '+':
      res = op1 + op2;
      break;
    case '-':
      res = op1 - op2;
      break;
    case '*':
      res = op1 * op2;
      break;
    case '/':
      res = op1 / op2;
      break;
    case '=':
      res = eval(expression);
      break;
  }
  result.innerHTML = res.toFixed(2);      // 显示结果，并保留两位小数
  inputBox.value = '';      // 清空输入框
  if (operator !== '=') {
    inputBox.value = res + operator;        // 将结果和运算符拼接成新的表达式
  }
}
```
