```csharp
using System;
using System.Collections.Generic;

// 卡牌类
public class Card {
    public string name; // 卡牌名称
    public int cost; // 卡牌费用
    public int attack; // 卡牌攻击力
    public int defense; // 卡牌防御力
    public string ability; // 卡牌特殊能力

    public Card(string name, int cost, int attack, int defense, string ability) {
        this.name = name;
        this.cost = cost;
        this.attack = attack;
        this.defense = defense;
        this.ability = ability;
    }
}

// 玩家类
public class Player {
    public string name; // 玩家名称
    public int health; // 玩家生命值
    public List<Card> hand; // 玩家手牌

    public Player(string name, int health) {
        this.name = name;
        this.health = health;
        this.hand = new List<Card>();
    }

    // 抽牌
    public void DrawCard(Card card) {
        hand.Add(card);
    }

    // 出牌
    public void PlayCard(Card card) {
        hand.Remove(card);
    }

    // 攻击
    public void Attack(Player target, int damage) {
        target.health -= damage;
    }
}

// 游戏类
public class Game {
    public Player player1; // 玩家1
    public Player player2; // 玩家2
    public List<Card> deck; // 牌库

    public Game(Player player1, Player player2, List<Card> deck) {
        this.player1 = player1;
        this.player2 = player2;
        this.deck = deck;
    }

    // 初始化游戏
    public void Init() {
        // 洗牌
        ShuffleDeck();

        // 发牌
        for (int i = 0; i < 3; i++) {
            player1.DrawCard(deck[0]);
            deck.RemoveAt(0);
            player2.DrawCard(deck[0]);
            deck.RemoveAt(0);
        }
    }

    // 洗牌
    public void ShuffleDeck() {
        Random rnd = new Random();
        for (int i = deck.Count - 1; i > 0; i--) {
            int j = rnd.Next(i + 1);
            Card temp = deck[i];
            deck[i] = deck[j];
            deck[j] = temp;
        }
    }

    // 开始游戏
    public void Start() {
        Init();

        while (player1.health > 0 && player2.health > 0) {
            // 玩家1回合
            PlayerTurn(player1, player2);

            // 玩家2回合
            PlayerTurn(player2, player1);
        }

        // 游戏结束
        if (player1.health <= 0) {
            Console.WriteLine(player2.name + " wins!");
        } else {
            Console.WriteLine(player1.name + " wins!");
        }
    }

    // 玩家回合
    public void PlayerTurn(Player player, Player target) {
        Console.WriteLine(player.name + "'s turn:");

        // 抽牌
        player.DrawCard(deck[0]);
        deck.RemoveAt(0);

        // 出牌
        foreach (Card card in player.hand) {
            if (card.cost <= player.health) {
                player.PlayCard(card);
                target.Attack(player, card.attack);
                Console.WriteLine(player.name + " plays " + card.name + " and deals " + card.attack + " damage to " + target.name);
                break;
            }
        }

        // 结束回合
        Console.WriteLine(player.name + " ends turn.");
    }
}

// 测试代码
public class Test {
    public static void Main() {
        // 创建卡牌
        Card card1 = new Card("Fireball", 3, 5, 0, "Deal 3 damage to target.");
        Card card2 = new Card("Frostbolt", 2, 3, 0, "Deal 2 damage to target and freeze it.");
        Card card3 = new Card("Healing Touch", 4, 0, 8, "Restore 8 health to target.");
        Card card4 = new Card("Charge", 1, 2, 0, "Charge and deal 2 damage to target.");

        // 创建玩家
        Player player1 = new Player("Alice", 30);
        Player player2 = new Player("Bob", 30);

        // 创建牌库
        List<Card> deck = new List<Card>();
        deck.Add(card1);
        deck.Add(card2);
        deck.Add(card3);
        deck.Add(card4);

        // 创建游戏
        Game game = new Game(player1, player2, deck);

        // 开始游戏
        game.Start();
    }
}
