```csharp
using FFmpeg.AutoGen;

namespace VideoWatermark
{
    class Program
    {
        static void AddWatermark(string inputFilePath, string outputFilePath, string watermarkText)
        {
            ffmpeg.av_register_all();

            AVFormatContext* formatContext = null;

            int result = ffmpeg.avformat_open_input(&formatContext, inputFilePath, null, null);
            if (result != 0)
            {
                throw new ApplicationException("Failed to open input file");
            }

            result = ffmpeg.avformat_find_stream_info(formatContext, null);
            if (result < 0)
            {
                throw new ApplicationException("Failed to find stream information");
            }

            int videoStreamIndex = -1;
            AVCodecParameters* codecParameters = null;

            for (int i = 0; i < formatContext->nb_streams; i++)
            {
                AVCodecParameters* parameters = formatContext->streams[i]->codecpar;
                if (parameters->codec_type == AVMediaType.AVMEDIA_TYPE_VIDEO)
                {
                    videoStreamIndex = i;
                    codecParameters = parameters;
                    break;
                }
            }

            if (videoStreamIndex == -1)
            {
                throw new ApplicationException("Failed to find video stream");
            }

            AVCodec* codec = ffmpeg.avcodec_find_decoder(codecParameters->codec_id);
            AVCodecContext* codecContext = ffmpeg.avcodec_alloc_context3(codec);

            result = ffmpeg.avcodec_parameters_to_context(codecContext, codecParameters);
            if (result < 0)
            {
                throw new ApplicationException("Failed to copy codec parameters to codec context");
            }

            result = ffmpeg.avcodec_open2(codecContext, codec, null);
            if (result < 0)
            {
                throw new ApplicationException("Failed to open codec");
            }

            AVPacket* packet = ffmpeg.av_packet_alloc();
            AVFrame* frame = ffmpeg.av_frame_alloc();

            AVFrame* outputFrame = ffmpeg.av_frame_alloc();
            int bufferSize = ffmpeg.av_image_get_buffer_size(codecParameters->format, codecParameters->width, codecParameters->height, 1);
            byte* buffer = (byte*)ffmpeg.av_malloc((ulong)bufferSize);
            ffmpeg.av_image_fill_arrays(outputFrame->data, outputFrame->linesize, buffer, codecParameters->format, codecParameters->width, codecParameters->height, 1);

            SwsContext* swsContext = ffmpeg.sws_getContext(codecParameters->width, codecParameters->height, codecContext->pix_fmt, codecParameters->width, codecParameters->height, AVPixelFormat.AV_PIX_FMT_BGR24, ffmpeg.SWS_BILINEAR, null, null, null);
            IntPtr textRgbaBuffer = IntPtr.Zero;
            int textRgbaBufferSize = ffmpeg.stbtt_GetScaledBitmapBox(&_font, 0, watermarkTextSize, Ascent, Descent, out _, out _);

            try
            {
                textRgbaBuffer = Marshal.AllocHGlobal(textRgbaBufferSize);
                ffmpeg.stbtt_MakeGlyphBitmap(&_font, (byte*)textRgbaBuffer, bitmapWidth, bitmapHeight, bitmapWidth, 1.0f, 1.0f, 0);
                for (int y = 0; y < codecParameters->height; y++)
                {
                    byte* outputRow = outputFrame->data[0] + y * outputFrame->linesize[0];
                    for (int x = 0; x < codecParameters->width; x++)
                    {
                        // 输出帧的 RGB 像素数据
                        byte* outputPixel = outputRow + x * 3;

                        outputPixel[0] = 255;
                        outputPixel[1] = 0;
                        outputPixel[2] = 0;
                    }
                }

                result = ffmpeg.avcodec_send_packet(codecContext, packet);
                if (result < 0)
                {
                    throw new ApplicationException("Failed to send packet to codec context");
                }

                result = ffmpeg.avcodec_receive_frame(codecContext, frame);
                if (result < 0)
                {
                    throw new ApplicationException("Failed to receive frame from codec context");
                }

                ffmpeg.av_packet_unref(packet);

                using (var fs = new FileStream(outputFilePath, FileMode.Create))
                {
                    var writer = new BinaryWriter(fs);

                    for (int y = 0; y < codecParameters->height; y++)
                    {
                        byte* outputRow = outputFrame->data[0] + y * outputFrame->linesize[0];
                        writer.Write(new ReadOnlySpan<byte>(outputRow, codecParameters->width * 3));
                    }
                }
            }
            finally
            {
                if (textRgbaBuffer != IntPtr.Zero)
                {
                    Marshal.FreeHGlobal(textRgbaBuffer);
                }

                ffmpeg.sws_freeContext(swsContext);
                ffmpeg.av_frame_free(&frame);
                ffmpeg.av_frame_free(&outputFrame);
                ffmpeg.av_packet_free(&packet);
                ffmpeg.avcodec_free_context(&codecContext);
                ffmpeg.avformat_close_input(&formatContext);
            }
        }

        static void Main(string[] args)
        {
            string inputFilePath = "input.mp4";
            string outputFilePath = "output.mp4";
            string watermarkText = "Hello, World!";

            AddWatermark(inputFilePath, outputFilePath, watermarkText);
        }
    }
}
