1. 将H264转换为H265：

const char* inFile = "input.h264";
const char* outFile = "output.h265";

static bool encode(const char* inFileName, const char* outFileName) {
  AVCodec* codec = avcodec_find_encoder(AV_CODEC_ID_HEVC);
  if (!codec) {
    fprintf(stderr, "Codec not found\n");
    return false;
  }

  AVCodecContext* codecCtx = avcodec_alloc_context3(codec);
  if (!codecCtx) {
    fprintf(stderr, "Could not allocate video codec context\n");
    return false;
  }

  codecCtx->width = 1920;
  codecCtx->height = 1080;
  codecCtx->bit_rate = 8000000;
  codecCtx->time_base = (AVRational){1, 25};
  codecCtx->framerate = (AVRational){25, 1};
  codecCtx->gop_size = 12;
  codecCtx->max_b_frames = 2;
  codecCtx->pix_fmt = AV_PIX_FMT_YUV420P;

  if (avcodec_open2(codecCtx, codec, NULL) < 0) {
    fprintf(stderr, "Could not open codec\n");
    return false;
  }

  AVFrame* frame = av_frame_alloc();
  if (!frame) {
    fprintf(stderr, "Could not allocate video frame\n");
    return false;
  }

  frame->format = codecCtx->pix_fmt;
  frame->width = codecCtx->width;
  frame->height = codecCtx->height;
  if (av_frame_get_buffer(frame, 0) < 0) {
    fprintf(stderr, "Could not allocate the video frame data\n");
    return false;
  }

  AVPacket pkt;
  av_init_packet(&pkt);
  pkt.data = NULL;
  pkt.size = 0;

  FILE* infile = fopen(inFileName, "rb");
  if (!infile) {
    fprintf(stderr, "Could not open %s\n", inFileName);
    return false;
  }

  FILE* outfile = fopen(outFileName, "wb");
  if (!outfile) {
    fprintf(stderr, "Could not open %s\n", outFileName);
    return false;
  }

  int frameNum = 0;
  while (!feof(infile)) {
    if (fread(frame->data[0], 1, codecCtx->width * codecCtx->height, infile) != codecCtx->width * codecCtx->height) {
      break;
    }
    if (fread(frame->data[1], 1, codecCtx->width * codecCtx->height / 4, infile) != codecCtx->width * codecCtx->height / 4) {
      break;
    }
    if (fread(frame->data[2], 1, codecCtx->width * codecCtx->height / 4, infile) != codecCtx->width * codecCtx->height / 4) {
      break;
    }

    frame->pts = frameNum;
    frameNum++;

    int ret = avcodec_send_frame(codecCtx, frame);
    if (ret < 0) {
      fprintf(stderr, "Error sending a frame for encoding\n");
      return false;
    }
    while (ret >= 0) {
      ret = avcodec_receive_packet(codecCtx, &pkt);
      if (ret == AVERROR(EAGAIN) || ret == AVERROR_EOF) {
        break;
      }
      if (ret < 0) {
        fprintf(stderr, "Error during encoding\n");
        return false;
      }

      fwrite(pkt.data, 1, pkt.size, outfile);
      av_packet_unref(&pkt);
    }
  }

  av_write_trailer(codecCtx);
  avcodec_free_context(&codecCtx);
  av_frame_free(&frame);

  fclose(infile);
  fclose(outfile);

  return true;
}

