const char* outFile = "output.g711a";

static bool encode(const char* inFileName, const char* outFileName) {
  AVCodec* codec = avcodec_find_encoder(AV_CODEC_ID_PCM_ALAW);
  if (!codec) {
    fprintf(stderr, "Codec not found\n");
    return false;
  }

  AVCodecContext* codecCtx = avcodec_alloc_context3(codec);
  if (!codecCtx) {
    fprintf(stderr, "Could not allocate audio codec context\n");
    return false;
  }

  codecCtx->sample_fmt = AV_SAMPLE_FMT_FLTP;
  codecCtx->bit_rate = 64000;
  codecCtx->sample_rate = 44100;
  codecCtx->channels = 2;
  codecCtx->channel_layout = AV_CH_LAYOUT_STEREO;

  if (avcodec_open2(codecCtx, codec, NULL) < 0) {
    fprintf(stderr, "Could not open codec\n");
    return false;
  }

  AVFrame* frame = av_frame_alloc();
  if (!frame) {
    fprintf(stderr, "Could not allocate audio frame\n");
    return false;
  }

  frame->nb_samples = codecCtx->frame_size;
  frame->format = codecCtx->sample_fmt;
  av_frame_get_buffer(frame, 0);

  AVPacket pkt;
  av_init_packet(&pkt);
  pkt.data = NULL;
  pkt.size = 0;

  FILE* infile = fopen(inFileName, "rb");
  if (!infile) {
    fprintf(stderr, "Could not open %s\n", inFileName);
    return false;
  }

  FILE* outfile = fopen(outFileName, "wb");
  if (!outfile) {
    fprintf(stderr, "Could not open %s\n", outFileName);
    return false;
  }

  int frameNum = 0;
  while (!feof(infile)) {
    if (fread(frame->extended_data[0], 1, codecCtx->channels * codecCtx->frame_size * sizeof(float), infile) != codecCtx->channels * codecCtx->frame_size * sizeof(float)) {
      break;
    }

    frame->pts = frameNum * codecCtx->frame_size;
    frameNum++;

    int ret = avcodec_send_frame(codecCtx, frame);
    if (ret < 0) {
      fprintf(stderr, "Error sending a frame for encoding\n");
      return false;
    }
    while (ret >= 0) {
      ret = avcodec_receive_packet(codecCtx, &pkt);
      if (ret == AVERROR(EAGAIN) || ret == AVERROR_EOF) {
        break;
      }
      if (ret < 0) {
        fprintf(stderr, "Error during encoding\n");
        return false;
      }

      fwrite(pkt.data, 1, pkt.size, outfile);
      av_packet_unref(&pkt);
    }
  }

  av_write_trailer(codecCtx);
  avcodec_free_context(&codecCtx);
  av_frame_free(&frame);

  fclose(infile);
  fclose(outfile);

  return true;
}

