您可以使用ffmpeg命令行工具中的rtmp输入和rtsp输出选项，读取rtmp流并将其转换为rtsp流。

您也可以使用libavformat库实现输入和输出。

下面是使用libavformat库读取rtmp流和写入rtsp流的c++代码片段：

AVFormatContext* inFmtCtx = NULL;
if (avformat_open_input(&inFmtCtx, "rtmp://localhost:1935/live/live1", NULL, NULL) != 0) {
  fprintf(stderr, "Could not open input file\n");
  return -1;
}

if (avformat_find_stream_info(inFmtCtx, NULL) < 0) {
  fprintf(stderr, "Could not find stream information\n");
  return -1;
}

AVFormatContext* outFmtCtx = NULL;
if (avformat_alloc_output_context2(&outFmtCtx, NULL, "rtsp", "rtsp://localhost:554/live/live1") < 0) {
  fprintf(stderr, "Could not allocate output context\n");
  return -1;
}

for (int i = 0; i < inFmtCtx->nb_streams; i++) {
  AVStream* inStream = inFmtCtx->streams[i];
  AVCodecParameters* inCodecPar = inStream->codecpar;

  enum AVMediaType codecType = inCodecPar->codec_type;
  AVCodec* codec = avcodec_find_decoder(inCodecPar->codec_id);
  if (!codec) {
    fprintf(stderr, "Could not find codec\n");
    return -1;
  }

  AVStream* outStream = avformat_new_stream(outFmtCtx, codec);
  if (!outStream) {
    fprintf(stderr, "Could not allocate output stream\n");
    return -1;
  }

  AVCodecParameters* outCodecPar = outStream->codecpar;
  avcodec_parameters_copy(outCodecPar, inCodecPar);
  outCodecPar->codec_tag = 0;
}

if (avformat_write_header(outFmtCtx, NULL) < 0) {
  fprintf(stderr, "Error writing header\n");
  return -1;
}

AVPacket pkt;
av_init_packet(&pkt);
pkt.data = NULL;
pkt.size = 0;

while (av_read_frame(inFmtCtx, &pkt) >= 0) {
  AVStream* inStream = inFmtCtx->streams[pkt.stream_index];
  AVStream* outStream = outFmtCtx->streams[pkt.stream_index];

  pkt.stream_index = outStream->index;

  if (av_interleaved_write_frame(outFmtCtx, &pkt) < 0) {
    fprintf(stderr, "Error muxing packet\n");
    break;
  }
  av_packet_unref(&pkt);
}

av_write_trailer(outFmtCtx);

avformat_close_input(&inFmtCtx);
avformat_free_context(outFmtCtx);

