            string vpnPassword = "password";
            string vpnDomain = "domain";
            string vpnConnectionName = "My VPN Connection";

            // Create the VPN connection
            ProcessStartInfo psi = new ProcessStartInfo("rasdial.exe", "\"" + vpnConnectionName + "\" " + vpnUsername + " " + vpnPassword);
            psi.UseShellExecute = false;
            psi.CreateNoWindow = true;
            psi.RedirectStandardOutput = true;
            Process process = Process.Start(psi);
            process.WaitForExit();

            // Set the VPN connection properties
            SetVpnConnectionProperties(vpnConnectionName, vpnServer, vpnDomain);

            Console.WriteLine("VPN connection established.");
            Console.ReadLine();
        }

        static void SetVpnConnectionProperties(string connectionName, string serverName, string domainName)
        {
            // Get the VPN connection handle
            IntPtr handle = IntPtr.Zero;
            RASCONN[] connections = new RASCONN[1];
            connections[0] = new RASCONN();
            connections[0].dwSize = Marshal.SizeOf(connections[0]);
            int result = RasEnumConnections(connections, ref handle, 1);
            if (result != 0)
