                throw new Exception("Failed to get VPN connection handle.");
            }

            // Get the VPN connection properties
            RASDIALPARAMS dialParams = new RASDIALPARAMS();
            dialParams.dwSize = Marshal.SizeOf(dialParams);
            dialParams.szEntryName = connectionName;
            result = RasGetEntryDialParams(null, ref dialParams, false);
