	"github.com/libp2p/go-libp2p-core/protocol"
	"github.com/libp2p/go-libp2p-core/routing"
	"github.com/libp2p/go-libp2p-kad-dht"
	"github.com/multiformats/go-multiaddr"
)

func main() {
	ctx := context.Background()

	// 创建一个libp2p主机
	host, err := libp2p.New(ctx)
	if err != nil {
		panic(err)
	}

	// 打印主机的多地址
	addrs, _ := host.Addrs()
	for _, addr := range addrs {
		fmt.Printf("我的地址是：%s/p2p/%s\n", addr, host.ID().Pretty())
	}

	// 创建一个DHT路由
	dht, err := dht.New(ctx, host)
	if err != nil {
		panic(err)
	}

	// 将DHT路由添加到主机中
	host.SetStreamHandler(protocol.ID("/dht"), dht)

	// 加入DHT网络
	if err := dht.Bootstrap(ctx); err != nil {
		panic(err)
	}

	// 在DHT中查找其他节点
	peerChan, err := dht.FindPeers(ctx, "my-protocol")
	if err != nil {
		panic(err)
	}

	// 连接到其他节点
	for peer := range peerChan {
		if peer.ID == host.ID() {
			continue
		}
		fmt.Printf("连接到节点：%s\n", peer.ID.Pretty())
		if err := host.Connect(ctx, peer); err != nil {
			fmt.Printf("连接到节点 %s 失败：%s\n", peer.ID.Pretty(), err)
		}
	}

	// 设置流处理程序
	host.SetStreamHandler(protocol.ID("my-protocol"), func(stream network.Stream) {
		fmt.Printf("收到来自 %s 的消息\n", stream.Conn().RemotePeer().Pretty())
	})

	// 发送消息到其他节点
	for _, peer := range host.Network().Peers() {
		if peer == host.ID() {
			continue
		}
		stream, err := host.NewStream(ctx, peer, protocol.ID("my-protocol"))
		if err != nil {
			fmt.Printf("发送消息到节点 %s 失败：%s\n", peer.Pretty(), err)
			continue
		}
		fmt.Printf("发送消息到节点 %s\n", peer.Pretty())
		if _, err := stream.Write([]byte("Hello, world!")); err != nil {
			fmt.Printf("发送消息到节点 %s 失败：%s\n", peer.Pretty(), err)
			continue
		}
	}

	// 等待一段时间
	time.Sleep(time.Second * 10)

	// 断开与一个节点的连接
	peer := host.Network().Peers()[0]
	host.Network().ClosePeer(peer)

	// 等待一段时间
	time.Sleep(time.Second * 10)

	// 重新连接到断开的节点
	if err := host.Connect(ctx, peer); err != nil {
		fmt.Printf("重新连接到节点 %s 失败：%s\n", peer.Pretty(), err)
	}

	// 等待一段时间
	time.Sleep(time.Second * 10)
}

```

这个示例代码与前面的示例代码类似，但它还演示了如何断开与一个节点的连接，并在一段时间后重新连接到该节点。这可以确保在出现故障时进行自愈。

