```java
import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class CityPopulation {

    public static void main(String[] args) {
        List<City> cities = readCitiesFromCSV("cities.csv");
        City mostPopulousCity = findMostPopulousCity(cities);
        System.out.println("Most populous city: " + mostPopulousCity.getName() + ", " + mostPopulousCity.getCountry() + ", population: " + mostPopulousCity.getPopulation() + ", last recorded year: " + mostPopulousCity.getLastRecordedYear());
        double[][] coordinates = getCityCoordinates(cities);
        System.out.println("City coordinates: " + java.util.Arrays.deepToString(coordinates));
    }

    private static List<City> readCitiesFromCSV(String fileName) {
        List<City> cities = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(fileName))) {
            String line;
            while ((line = br.readLine()) != null) {
                String[] values = line.split(",");
                String name = values[0];
                String country = values[1];
                int population = Integer.parseInt(values[2]);
                int lastRecordedYear = Integer.parseInt(values[3]);
                cities.add(new City(name, country, population, lastRecordedYear));
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        return cities;
    }

    private static City findMostPopulousCity(List<City> cities) {
        Collections.sort(cities, new Comparator<City>() {
            @Override
            public int compare(City c1, City c2) {
                return c2.getPopulation() - c1.getPopulation();
            }
        });
        return cities.get(0);
    }

    private static double[][] getCityCoordinates(List<City> cities) {
        double[][] coordinates = new double[cities.size()][2];
        for (int i = 0; i < cities.size(); i++) {
            String name = cities.get(i).getName();
            int[] digits = name.chars().map(c -> Character.isLetter(c) ? Character.toLowerCase(c) - 'a' + 1 : 0).toArray();
            int x = 0;
            int y = 0;
            for (int j = 0; j < digits.length; j++) {
                if (j % 2 == 0) {
                    x += digits[j];
                } else {
                    y += digits[j];
                }
            }
            coordinates[i][0] = x * 0.1;
            coordinates[i][1] = y * 0.1;
        }
        return coordinates;
    }

    private static class City {
        private String name;
        private String country;
        private int population;
        private int lastRecordedYear;

        public City(String name, String country, int population, int lastRecordedYear) {
            this.name = name;
            this.country = country;
            this.population = population;
            this.lastRecordedYear = lastRecordedYear;
        }

        public String getName() {
            return name;
        }

        public String getCountry() {
            return country;
        }

        public int getPopulation() {
            return population;
        }

        public int getLastRecordedYear() {
            return lastRecordedYear;
        }
    }
}
```

